mapper.select:
SELECT * FROM (
    SELECT ROWNUM AS rn, a.* FROM (
        SELECT 
            COUNTER_ID, 
            CURRENT_COUNT, 
            LAST_UPDATE
        FROM ANIMAL_COUNTER

        ORDER BY COUNTER_ID ASC
    ) a WHERE ROWNUM <= #{endRow}
) WHERE rn >= #{startRow}

